import urllib.request
import urllib.error
import time
import json

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"
        last_exception = None

        # Handle 4xx and 5xx with retries
        while True:
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    code = response.getcode()
                    if code == 429:
                        # Rate limit: retry up to 3 times with exponential backoff
                        if last_exception is not None:
                            # Check if we've already retried 3 times
                            if last_exception.count >= 3:
                                raise RateLimitError("Rate limit exceeded after 3 retries")
                            time.sleep(last_exception.backoff)
                            continue
                        else:
                            last_exception = Exception(backoff=0.5)
                            time.sleep(last_exception.backoff)
                            continue
                    elif 500 <= code < 600:
                        # Server error: retry once after 1s
                        if last_exception is not None:
                            raise ServerError("Server error after retry")
                        time.sleep(1)
                        continue
                    elif 400 <= code < 500 and code != 429:
                        # Client error: raise immediately
                        raise ClientError(f"Client error {code}")
                    else:
                        # Success
                        return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                code = e.code
                if code == 429:
                    if last_exception is not None:
                        if last_exception.count >= 3:
                            raise RateLimitError("Rate limit exceeded after 3 retries")
                        time.sleep(last_exception.backoff)
                        continue
                    else:
                        last_exception = Exception(backoff=0.5)
                        time.sleep(last_exception.backoff)
                        continue
                elif 500 <= code < 600:
                    if last_exception is not None:
                        raise ServerError("Server error after retry")
                    time.sleep(1)
                    continue
                elif 400 <= code < 500 and code != 429:
                    raise ClientError(f"Client error {code}")
                else:
                    raise
            except urllib.error.URLError as e:
                # Network error: retry once after 1s
                if last_exception is not None:
                    raise ConnectionError("Connection error after retry")
                time.sleep(1)
                continue
            except Exception as e:
                raise

    def _handle_rate_limit(self, backoff):
        if last_exception is not None:
            if last_exception.count >= 3:
                raise RateLimitError("Rate limit exceeded after 3 retries")
            time.sleep(last_exception.backoff)
            continue
        else:
            last_exception = Exception(backoff=0.5)
            time.sleep(last_exception.backoff)
            continue
